const body = $json.body ?? $json;
const organization_id = body.organization_id;
const items = body.items;

if (!organization_id || typeof organization_id !== 'string') {
  throw new Error('organization_id is required');
}
if (!Array.isArray(items) || items.length === 0) {
  throw new Error('items must be a non-empty array');
}

const normalized = items.map((item, index) => {
  const sku = String(item.sku ?? '').trim();
  const requested_quantity = Number(item.requested_quantity);
  if (!sku) throw new Error(`items[${index}].sku is required`);
  if (!Number.isInteger(requested_quantity) || requested_quantity <= 0) {
    throw new Error(`items[${index}].requested_quantity must be a positive integer`);
  }
  return { sku, requested_quantity };
});

return [{
  json: {
    organization_id,
    request_id: String(body.request_id ?? $execution.id),
    items: normalized,
    received_at: new Date().toISOString()
  }
}];

const request = $('Validate request').first().json;
const returned = $input.all().flatMap(item => {
  if (Array.isArray(item.json)) return item.json;
  if (Array.isArray(item.json.body)) return item.json.body;
  return [item.json];
}).filter(row => row && row.sku);

const bySku = new Map(returned.map(product => [product.sku, product]));
const results = request.items.map(requested => {
  const product = bySku.get(requested.sku);

  if (!product) {
    return {
      sku: requested.sku,
      requested_quantity: requested.requested_quantity,
      found: false,
      shortage: true,
      recommendation: 'Product SKU was not found for this organization',
      suggested_reorder_quantity: null
    };
  }

  const stock = Number(product.stock_quantity ?? 0);
  const reorderLevel = Number(product.reorder_level ?? 0);
  const requestedQty = requested.requested_quantity;
  const shortageQty = Math.max(0, requestedQty - stock);
  const projectedStock = stock - requestedQty;
  const needsReorder = projectedStock < reorderLevel;
  const suggestedQty = needsReorder
    ? Math.max(shortageQty, reorderLevel - projectedStock)
    : 0;

  return {
    product_id: product.id,
    sku: product.sku,
    product_name: product.name,
    found: true,
    current_stock: stock,
    requested_quantity: requestedQty,
    shortage: shortageQty > 0,
    shortage_quantity: shortageQty,
    projected_stock_after_request: projectedStock,
    reorder_level: reorderLevel,
    needs_reorder: needsReorder,
    suggested_reorder_quantity: suggestedQty,
    recommendation: shortageQty > 0
      ? `Short by ${shortageQty} units; replenish ${suggestedQty} units`
      : needsReorder
        ? `Request can be fulfilled; replenish ${suggestedQty} units to restore buffer`
        : 'Sufficient stock available'
  };
});

const shortages = results.filter(r => r.found && r.shortage);
const missing = results.filter(r => !r.found);
const reorderRecommendations = results.filter(r => r.found && r.needs_reorder);

const response = {
  success: missing.length === 0,
  request_id: request.request_id,
  organization_id: request.organization_id,
  checked_at: new Date().toISOString(),
  summary: {
    items_checked: results.length,
    shortage_count: shortages.length,
    missing_sku_count: missing.length,
    reorder_recommendation_count: reorderRecommendations.length
  },
  items: results,
  reorder_recommendations: reorderRecommendations
};

return [{
  json: {
    organization_id: request.organization_id,
    request_id: request.request_id,
    request_payload: { items: request.items },
    result: response,
    status: missing.length ? 'needs_review' : shortages.length ? 'shortage' : 'ok'
  }
}];
